import { redirect } from "next/navigation";
import Link from "next/link";
import { authErrorMessage, currentUser } from "@/lib/auth";
import { CartWaiting } from "@/app/components/CartWaiting";
import { listOrdersForCustomer } from "@/lib/orders";
import { EmptyState } from "@/app/components/EmptyState";
import { formatCents, formatDateTime, STATUS_LABELS } from "@/lib/format";

export default async function AccountOrdersPage({ searchParams }: { searchParams: { error?: string } }) {
  const user = await currentUser();
  if (!user) redirect("/signin");

  const orders = await listOrdersForCustomer(user.id);
  const errorMessage = authErrorMessage(searchParams.error);

  return (
    <main className="mx-auto max-w-2xl px-4 py-10 sm:px-6">
      <h1 className="font-display text-3xl font-semibold tracking-tight text-text">Your orders</h1>
      <p className="mt-1 truncate text-sm text-textMuted">Signed in as {user.email}</p>

      {errorMessage && (
        <p className="mt-4 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{errorMessage}</p>
      )}

      <div className="mt-6">
        <CartWaiting />
      </div>

      <form action="/api/logout" method="POST" className="mt-2">
        <button type="submit" className="text-xs font-medium text-textMuted hover:text-accent">
          Sign out
        </button>
      </form>

      {orders.length === 0 ? (
        <div className="mt-8">
          <EmptyState title="No orders yet" hint="Once you place an order, it'll show up here." />
          <div className="mt-6 flex justify-center">
            <Link href="/shop" className="text-sm font-semibold text-accent hover:underline">
              Find a cake for your occasion
            </Link>
          </div>
        </div>
      ) : (
        <div className="mt-8 flex flex-col gap-3">
          {orders.map((order) => (
            <Link
              key={order.id}
              href={`/orders/${order.id}`}
              className="flex items-center justify-between gap-4 rounded-xl border border-border bg-surface p-4 shadow-sm hover:bg-surface2/60"
            >
              <div className="min-w-0">
                <p className="font-medium text-text">Order #{order.id}</p>
                <p className="truncate text-sm text-textMuted">{formatDateTime(order.fulfillment_at)}</p>
              </div>
              <div className="flex flex-shrink-0 flex-col items-end gap-1">
                <span className="rounded-full bg-surface2 px-2.5 py-0.5 text-xs font-medium text-textMuted">
                  {STATUS_LABELS[order.status] ?? order.status}
                </span>
                <span className="font-semibold text-text">{formatCents(order.total_cents)}</span>
              </div>
            </Link>
          ))}
        </div>
      )}
    </main>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { requireAdminAction } from "@/lib/auth";
import { query, withTransaction } from "@/lib/db";
import { updateOrderStatus, type OrderStatus } from "@/lib/orders";
import { OCCASIONS, OPTION_KINDS, parseTags } from "@/lib/catalog-config";

const VALID_STATUSES: OrderStatus[] = [
  "pending",
  "paid",
  "in_kitchen",
  "ready",
  "out_for_delivery",
  "completed",
  "cancelled",
];

// Starter customization choices for a new cake, so shoppers can order it right
// away. Staff can edit or remove any of these on the cake's edit page.
const DEFAULT_OPTIONS: { kind: string; label: string; delta: number; sort: number }[] = [
  { kind: "size", label: '6" (serves 8)', delta: 0, sort: 1 },
  { kind: "size", label: '8" (serves 14)', delta: 1200, sort: 2 },
  { kind: "size", label: '10" (serves 24)', delta: 2600, sort: 3 },
  { kind: "flavor", label: "Vanilla", delta: 0, sort: 1 },
  { kind: "flavor", label: "Chocolate", delta: 0, sort: 2 },
  { kind: "frosting", label: "Buttercream", delta: 0, sort: 1 },
  { kind: "frosting", label: "Cream Cheese", delta: 300, sort: 2 },
];

function slugify(name: string): string {
  return (
    name
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, "")
      .slice(0, 60) || "cake"
  );
}

function dollarsToCents(raw: FormDataEntryValue | null): number | null {
  const n = Number(raw ?? "");
  if (!Number.isFinite(n) || n < 0 || n > 100000) return null;
  return Math.round(n * 100);
}

function readOccasions(formData: FormData): string[] {
  const picked = formData.getAll("occasion").map(String);
  const valid = picked.filter((o) => OCCASIONS.some((x) => x.slug === o));
  return valid.length > 0 ? valid : ["custom"];
}

function revalidateCatalog(slug?: string) {
  revalidatePath("/admin");
  revalidatePath("/shop");
  revalidatePath("/");
  if (slug) revalidatePath(`/cakes/${slug}`);
}

export async function addCakeAction(formData: FormData): Promise<void> {
  await requireAdminAction();
  const name = String(formData.get("name") ?? "").trim().slice(0, 200);
  const description = String(formData.get("description") ?? "").trim().slice(0, 2000);
  const price = dollarsToCents(formData.get("price"));
  if (!name || price === null || price <= 0) redirect("/admin?error=cake");

  const occasions = readOccasions(formData);
  const dietary = parseTags(String(formData.get("dietary") ?? ""));
  const base = slugify(name);

  const cakeId = await withTransaction(async (c) => {
    const taken = await c.query<{ slug: string }>("SELECT slug FROM cakes WHERE slug = $1 OR slug LIKE $2", [
      base,
      `${base}-%`,
    ]);
    const used = new Set(taken.rows.map((r) => r.slug));
    let slug = base;
    for (let n = 2; used.has(slug); n++) slug = `${base}-${n}`;
    const inserted = await c.query<{ id: number }>(
      `INSERT INTO cakes (slug, name, description, base_price_cents, occasion_tags, dietary_tags, is_sample)
       VALUES ($1, $2, $3, $4, $5::text[], $6::text[], false) RETURNING id`,
      [slug, name, description, price, occasions, dietary],
    );
    const id = inserted.rows[0].id;
    for (const o of DEFAULT_OPTIONS) {
      await c.query(
        "INSERT INTO cake_options (cake_id, kind, label, price_delta_cents, sort_order) VALUES ($1, $2, $3, $4, $5)",
        [id, o.kind, o.label, o.delta, o.sort],
      );
    }
    return id;
  });
  revalidateCatalog();
  redirect(`/admin/cakes/${cakeId}?saved=created`);
}

export async function updateCakeAction(formData: FormData): Promise<void> {
  await requireAdminAction();
  const cakeId = Number(formData.get("cakeId"));
  if (!Number.isInteger(cakeId)) return;
  const name = String(formData.get("name") ?? "").trim().slice(0, 200);
  const description = String(formData.get("description") ?? "").trim().slice(0, 2000);
  const price = dollarsToCents(formData.get("price"));
  if (!name || price === null || price <= 0) redirect(`/admin/cakes/${cakeId}?error=invalid`);
  const occasions = readOccasions(formData);
  const dietary = parseTags(String(formData.get("dietary") ?? ""));
  const active = formData.get("active") === "on";

  const r = await query<{ slug: string }>(
    `UPDATE cakes SET name = $2, description = $3, base_price_cents = $4, occasion_tags = $5::text[],
       dietary_tags = $6::text[], active = $7
     WHERE id = $1 RETURNING slug`,
    [cakeId, name, description, price, occasions, dietary, active],
  );
  revalidateCatalog(r.rows[0]?.slug);
  redirect(`/admin/cakes/${cakeId}?saved=1`);
}

export async function addOptionAction(formData: FormData): Promise<void> {
  await requireAdminAction();
  const cakeId = Number(formData.get("cakeId"));
  const kind = String(formData.get("kind") ?? "");
  const label = String(formData.get("label") ?? "").trim().slice(0, 100);
  const delta = dollarsToCents(formData.get("delta") || "0");
  if (!Number.isInteger(cakeId) || !OPTION_KINDS.some((k) => k.kind === kind) || !label || delta === null) {
    redirect(`/admin/cakes/${cakeId}?error=option`);
  }
  const dup = await query("SELECT 1 FROM cake_options WHERE cake_id = $1 AND kind = $2 AND label = $3", [
    cakeId,
    kind,
    label,
  ]);
  if (dup.rows.length > 0) redirect(`/admin/cakes/${cakeId}?error=duplicate`);
  const r = await query<{ slug: string }>(
    `WITH ins AS (
       INSERT INTO cake_options (cake_id, kind, label, price_delta_cents, sort_order)
       SELECT $1, $2, $3, $4, COALESCE(MAX(sort_order), 0) + 1 FROM cake_options WHERE cake_id = $1 AND kind = $2
       RETURNING cake_id
     )
     SELECT c.slug FROM cakes c JOIN ins ON ins.cake_id = c.id`,
    [cakeId, kind, label, delta],
  );
  revalidateCatalog(r.rows[0]?.slug);
  redirect(`/admin/cakes/${cakeId}?saved=1`);
}

export async function deleteOptionAction(formData: FormData): Promise<void> {
  await requireAdminAction();
  const cakeId = Number(formData.get("cakeId"));
  const optionId = Number(formData.get("optionId"));
  if (!Number.isInteger(cakeId) || !Number.isInteger(optionId)) return;
  // Past orders keep a snapshot of the chosen options, so removing a choice
  // here never changes an existing order.
  await query("DELETE FROM cake_options WHERE id = $1 AND cake_id = $2", [optionId, cakeId]);
  const r = await query<{ slug: string }>("SELECT slug FROM cakes WHERE id = $1", [cakeId]);
  revalidateCatalog(r.rows[0]?.slug);
  redirect(`/admin/cakes/${cakeId}?saved=1`);
}

export async function toggleCakeActiveAction(formData: FormData): Promise<void> {
  await requireAdminAction();
  const cakeId = Number(formData.get("cakeId"));
  if (!Number.isInteger(cakeId)) return;
  const r = await query<{ slug: string }>("UPDATE cakes SET active = NOT active WHERE id = $1 RETURNING slug", [cakeId]);
  revalidateCatalog(r.rows[0]?.slug);
}

export async function updateOrderStatusAction(formData: FormData): Promise<void> {
  await requireAdminAction();
  const orderId = Number(formData.get("orderId"));
  const status = String(formData.get("status") ?? "") as OrderStatus;
  if (!Number.isInteger(orderId) || !VALID_STATUSES.includes(status)) return;
  await updateOrderStatus(orderId, status);
  revalidatePath("/admin");
  revalidatePath(`/admin/orders/${orderId}`);
  revalidatePath(`/orders/${orderId}`);
  revalidatePath("/account/orders");
}

export async function removeSampleDataAction(): Promise<void> {
  await requireAdminAction();
  // Sample cakes nobody has ordered are removed outright. Any sample cake that
  // already appears on an order is hidden instead, so that order stays intact.
  await withTransaction(async (c) => {
    await c.query(
      `DELETE FROM cake_options WHERE cake_id IN (
         SELECT id FROM cakes WHERE is_sample = true
         AND NOT EXISTS (SELECT 1 FROM order_items oi WHERE oi.cake_id = cakes.id))`,
    );
    await c.query(
      `DELETE FROM cakes WHERE is_sample = true
       AND NOT EXISTS (SELECT 1 FROM order_items oi WHERE oi.cake_id = cakes.id)`,
    );
    await c.query("UPDATE cakes SET active = false WHERE is_sample = true");
  });
  revalidateCatalog();
}

import Link from "next/link";
import { requireAdminPage } from "@/lib/auth";
import { listAllCakesForAdmin, hasSampleCakes } from "@/lib/cakes";
import { listAllOrders } from "@/lib/orders";
import { formatCents, formatDateTime, STATUS_LABELS } from "@/lib/format";
import { OCCASIONS } from "@/lib/catalog-config";
import { EmptyState } from "@/app/components/EmptyState";
import { Button } from "@/app/components/ui/button";
import { addCakeAction, removeSampleDataAction, toggleCakeActiveAction } from "@/app/admin/actions";

const FIELD = "rounded-lg border border-border bg-surface px-3 py-2 text-sm text-text outline-none focus:border-accent";

const FILTERS = [
  { key: "open", label: "Open", match: (s: string) => !["completed", "cancelled"].includes(s) },
  { key: "pending", label: "New", match: (s: string) => s === "pending" },
  { key: "all", label: "All", match: () => true },
] as const;

const STATUS_TONE: Record<string, string> = {
  pending: "bg-amber-100 text-amber-800",
  paid: "bg-sky-100 text-sky-800",
  in_kitchen: "bg-violet-100 text-violet-800",
  ready: "bg-emerald-100 text-emerald-800",
  out_for_delivery: "bg-emerald-100 text-emerald-800",
  completed: "bg-surface2 text-textMuted",
  cancelled: "bg-red-100 text-red-700",
};

export default async function AdminPage({ searchParams }: { searchParams: { view?: string; error?: string } }) {
  await requireAdminPage();
  const [orders, cakes, sample] = await Promise.all([listAllOrders(), listAllCakesForAdmin(), hasSampleCakes()]);
  const filter = FILTERS.find((f) => f.key === searchParams.view) ?? FILTERS[0];
  const shown = orders
    .filter((o) => filter.match(o.status))
    .sort((a, b) =>
      filter.key === "all" ? 0 : new Date(a.fulfillment_at).getTime() - new Date(b.fulfillment_at).getTime(),
    );
  const newCount = orders.filter((o) => o.status === "pending").length;

  return (
    <main className="mx-auto max-w-5xl px-4 py-10 sm:px-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="font-display text-3xl font-semibold tracking-tight text-text">Staff admin</h1>
          <p className="mt-1 text-sm text-textMuted">
            {newCount > 0 ? `${newCount} new order${newCount === 1 ? "" : "s"} waiting for confirmation.` : "No new orders right now."}
          </p>
        </div>
        {sample && (
          <form action={removeSampleDataAction}>
            <Button type="submit" variant="outline" size="sm">
              Remove sample cakes
            </Button>
          </form>
        )}
      </div>

      <section className="mt-8">
        <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
          <h2 className="font-display text-xl font-semibold text-text">Orders</h2>
          <div className="flex rounded-lg border border-border p-1 text-sm">
            {FILTERS.map((f) => (
              <Link
                key={f.key}
                href={`/admin?view=${f.key}`}
                className={`rounded-md px-3 py-1 font-medium ${
                  f.key === filter.key ? "bg-accent text-accentFg" : "text-textMuted hover:text-text"
                }`}
              >
                {f.label}
              </Link>
            ))}
          </div>
        </div>
        {shown.length === 0 ? (
          <EmptyState title="No orders here" hint="New orders show up as soon as a customer checks out." />
        ) : (
          <div className="flex flex-col gap-2">
            {shown.map((order) => (
              <Link
                key={order.id}
                href={`/admin/orders/${order.id}`}
                className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border bg-surface p-4 transition hover:bg-surface2/60"
              >
                <div className="min-w-0 flex-1">
                  <p className="truncate font-medium text-text">
                    #{order.id} · {order.contact_name}
                  </p>
                  <p className="truncate text-sm text-textMuted">
                    <span className="capitalize">{order.fulfillment}</span> · {formatDateTime(order.fulfillment_at)}
                  </p>
                </div>
                <div className="flex flex-shrink-0 items-center gap-3">
                  <span
                    className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${STATUS_TONE[order.status] ?? "bg-surface2 text-textMuted"}`}
                  >
                    {STATUS_LABELS[order.status] ?? order.status}
                  </span>
                  <span className="font-semibold text-text">{formatCents(order.total_cents)}</span>
                </div>
              </Link>
            ))}
          </div>
        )}
      </section>

      <section className="mt-12">
        <h2 className="mb-3 font-display text-xl font-semibold text-text">Cakes</h2>
        {cakes.length === 0 ? (
          <EmptyState title="No cakes yet" hint="Add your first cake below and it will appear in the shop." />
        ) : (
          <div className="mb-6 flex flex-col gap-2">
            {cakes.map((cake) => (
              <div key={cake.id} className="flex items-center justify-between gap-4 rounded-xl border border-border bg-surface p-4">
                <div className="min-w-0">
                  <p className="truncate font-medium text-text">
                    {cake.name}
                    {cake.is_sample && <span className="ml-2 text-xs text-textMuted">(sample)</span>}
                    {!cake.active && <span className="ml-2 text-xs text-textMuted">(hidden)</span>}
                  </p>
                  <p className="text-sm text-textMuted">from {formatCents(cake.base_price_cents)}</p>
                </div>
                <div className="flex flex-shrink-0 items-center gap-2">
                  <Button asChild size="sm" variant="ghost">
                    <Link href={`/admin/cakes/${cake.id}`}>Edit</Link>
                  </Button>
                  <form action={toggleCakeActiveAction}>
                    <input type="hidden" name="cakeId" value={cake.id} />
                    <Button type="submit" size="sm" variant={cake.active ? "outline" : "default"}>
                      {cake.active ? "Hide" : "Show"}
                    </Button>
                  </form>
                </div>
              </div>
            ))}
          </div>
        )}

        <div className="rounded-xl border border-border bg-surface p-5">
          <h3 className="mb-4 font-display text-lg font-semibold text-text">Add a cake</h3>
          {searchParams.error === "cake" && (
            <p className="mb-3 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">
              Give the cake a name and a price above $0.
            </p>
          )}
          <form action={addCakeAction} className="grid gap-3 sm:grid-cols-2">
            <input name="name" placeholder="Cake name" required maxLength={200} className={`${FIELD} sm:col-span-2`} />
            <textarea name="description" placeholder="Description" rows={2} maxLength={2000} className={`${FIELD} sm:col-span-2`} />
            <input name="price" type="number" min="1" step="0.01" placeholder="Base price (USD)" required className={FIELD} />
            <input name="dietary" placeholder="Dietary tags, e.g. gluten-free" className={FIELD} />
            <fieldset className="sm:col-span-2">
              <legend className="mb-2 text-sm font-medium text-text">Occasions</legend>
              <div className="flex flex-wrap gap-4">
                {OCCASIONS.map((o) => (
                  <label key={o.slug} className="flex items-center gap-2 text-sm text-text">
                    <input type="checkbox" name="occasion" value={o.slug} defaultChecked={o.slug === "birthday"} />
                    {o.label}
                  </label>
                ))}
              </div>
            </fieldset>
            <Button type="submit" className="sm:col-span-2">
              Add cake
            </Button>
          </form>
        </div>
      </section>
    </main>
  );
}

import { NextResponse } from "next/server";
import { currentUser, isCrossSiteRequest, forbidden } from "@/lib/auth";
import { createOrder, earliestFulfillment, OrderValidationError, parseOrderLines } from "@/lib/orders";

const MAX_ADVANCE_DAYS = 180;

export async function POST(req: Request): Promise<NextResponse> {
  if (isCrossSiteRequest(req)) return forbidden();
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  let body: Record<string, unknown>;
  try {
    body = (await req.json()) as Record<string, unknown>;
  } catch {
    return NextResponse.json({ error: "bad_request" }, { status: 400 });
  }
  if (!body || typeof body !== "object") return NextResponse.json({ error: "bad_request" }, { status: 400 });

  const fulfillment = body.fulfillment;
  const contactName = String(body.contactName ?? "").trim().slice(0, 200);
  const contactPhone = String(body.contactPhone ?? "").trim().slice(0, 40);
  const address = String(body.address ?? "").trim().slice(0, 400);
  const notes = String(body.notes ?? "").trim().slice(0, 1000);
  const fulfillmentAt = new Date(String(body.fulfillmentAt ?? ""));

  if ((fulfillment !== "pickup" && fulfillment !== "delivery") || !contactName || !contactPhone) {
    return NextResponse.json({ error: "bad_request" }, { status: 400 });
  }
  if (fulfillment === "delivery" && !address) {
    return NextResponse.json({ error: "missing_address" }, { status: 400 });
  }
  if (
    Number.isNaN(fulfillmentAt.getTime()) ||
    fulfillmentAt < earliestFulfillment() ||
    fulfillmentAt.getTime() > Date.now() + MAX_ADVANCE_DAYS * 24 * 60 * 60 * 1000
  ) {
    return NextResponse.json({ error: "bad_date" }, { status: 400 });
  }

  try {
    const items = parseOrderLines(body.items);
    const orderId = await createOrder({
      customerId: user.id,
      fulfillment,
      fulfillmentAt,
      contactName,
      contactPhone,
      address: fulfillment === "delivery" ? address : null,
      notes: notes || null,
      items,
    });
    return NextResponse.json({ orderId });
  } catch (e) {
    if (e instanceof OrderValidationError) {
      return NextResponse.json({ error: e.message }, { status: 400 });
    }
    console.error("[orders] create failed", (e as { code?: string })?.code ?? "unknown");
    return NextResponse.json({ error: "server" }, { status: 500 });
  }
}

import Link from "next/link";
import { Button } from "@/app/components/ui/button";
import { CheckoutForm } from "@/app/components/CheckoutForm";
import { currentUser } from "@/lib/auth";

export default async function CheckoutPage() {
  const user = await currentUser();

  return (
    <main className="mx-auto max-w-lg px-4 py-10 sm:px-6">
      <h1 className="font-display text-3xl font-semibold tracking-tight text-text">Checkout</h1>
      {!user ? (
        <div className="mt-8 flex flex-col items-center gap-4 rounded-xl border border-border bg-surface p-8 text-center">
          <p className="text-textMuted">Sign in to place your order — your cart will be waiting for you.</p>
          <Button asChild size="lg">
            <Link href="/signin?mode=signup">Sign in / Create account</Link>
          </Button>
        </div>
      ) : (
        <div className="mt-8">
          <CheckoutForm defaultName={user.name ?? ""} defaultPhone={user.phone ?? ""} />
        </div>
      )}
    </main>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/app/components/ui/button";
import { formatCents } from "@/lib/format";
import { useCart } from "@/lib/cart-context";

const DELIVERY_FEE_CENTS = 1200;
const MIN_LEAD_HOURS = 24;

const ERROR_COPY: Record<string, string> = {
  bad_date: `Pick a time at least ${MIN_LEAD_HOURS} hours from now so we have time to bake it fresh.`,
  missing_address: "Enter a delivery address.",
  cake_unavailable: "One of the cakes in your cart is no longer available. Please remove it from your cart and try again.",
  option_unavailable: "One of your cake choices has changed. Please remove that cake from your cart and customize it again.",
  bad_items: "Something in your cart looks off. Please review your cart and try again.",
  unauthorized: "Your session expired. Please sign in again.",
};

/** yyyy-MM-ddTHH:mm in the browser's local time, for datetime-local min. */
function toLocalInputValue(d: Date): string {
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

export function CheckoutForm({ defaultName, defaultPhone }: { defaultName: string; defaultPhone: string }) {
  const router = useRouter();
  const { items, subtotalCents, clear } = useCart();
  const [fulfillment, setFulfillment] = useState<"pickup" | "delivery">("pickup");
  const [contactName, setContactName] = useState(defaultName);
  const [contactPhone, setContactPhone] = useState(defaultPhone);
  const [address, setAddress] = useState("");
  const [date, setDate] = useState("");
  const [notes, setNotes] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [minDate, setMinDate] = useState<string | undefined>(undefined);

  useEffect(() => {
    setMinDate(toLocalInputValue(new Date(Date.now() + MIN_LEAD_HOURS * 60 * 60 * 1000)));
  }, []);

  const deliveryFee = fulfillment === "delivery" ? DELIVERY_FEE_CENTS : 0;
  const total = subtotalCents + deliveryFee;

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    if (!date) {
      setError("Choose a pickup or delivery date.");
      return;
    }
    if (fulfillment === "delivery" && !address.trim()) {
      setError("Enter a delivery address.");
      return;
    }
    if (new Date(date).getTime() < Date.now() + MIN_LEAD_HOURS * 60 * 60 * 1000) {
      setError(ERROR_COPY.bad_date);
      return;
    }
    if (items.length === 0) {
      setError("Your cart is empty.");
      return;
    }
    setSubmitting(true);
    try {
      const res = await fetch("/api/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          fulfillment,
          fulfillmentAt: new Date(date).toISOString(),
          contactName,
          contactPhone,
          address: fulfillment === "delivery" ? address : null,
          notes,
          items: items.map((item) => ({
            cakeId: item.cakeId,
            quantity: item.quantity,
            selectedOptions: item.selectedOptions.map((o) => ({ kind: o.kind, label: o.label })),
            messageOnCake: item.messageOnCake,
          })),
        }),
      });
      if (!res.ok) {
        const data = (await res.json().catch(() => ({}))) as { error?: string };
        setError((data.error && ERROR_COPY[data.error]) || "Something went wrong placing your order. Try again.");
        setSubmitting(false);
        return;
      }
      const data = await res.json();
      clear();
      router.push(`/orders/${data.orderId}`);
    } catch {
      setError("Something went wrong placing your order. Try again.");
      setSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-5">
      <div className="flex gap-2">
        {(["pickup", "delivery"] as const).map((option) => (
          <button
            key={option}
            type="button"
            onClick={() => setFulfillment(option)}
            className={`flex-1 rounded-lg border px-4 py-2.5 text-sm font-medium capitalize transition ${
              fulfillment === option
                ? "border-accent bg-accent text-accentFg"
                : "border-border bg-surface text-text hover:bg-surface2"
            }`}
          >
            {option}
          </button>
        ))}
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
          Name
          <input
            required
            value={contactName}
            onChange={(e) => setContactName(e.target.value)}
            className="rounded-lg border border-border bg-surface px-3 py-2 text-sm outline-none focus:border-accent"
          />
        </label>
        <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
          Phone
          <input
            required
            value={contactPhone}
            onChange={(e) => setContactPhone(e.target.value)}
            className="rounded-lg border border-border bg-surface px-3 py-2 text-sm outline-none focus:border-accent"
          />
        </label>
      </div>

      {fulfillment === "delivery" && (
        <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
          Delivery address
          <input
            required
            value={address}
            onChange={(e) => setAddress(e.target.value)}
            className="rounded-lg border border-border bg-surface px-3 py-2 text-sm outline-none focus:border-accent"
          />
        </label>
      )}

      <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
        {fulfillment === "pickup" ? "Pickup date & time" : "Delivery date & time"}
        <span className="text-xs font-normal text-textMuted">
          We need at least {MIN_LEAD_HOURS} hours to bake your cake fresh.
        </span>
        <input
          required
          type="datetime-local"
          min={minDate}
          value={date}
          onChange={(e) => setDate(e.target.value)}
          className="rounded-lg border border-border bg-surface px-3 py-2 text-sm outline-none focus:border-accent"
        />
      </label>

      <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
        Order notes (optional)
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          rows={3}
          className="rounded-lg border border-border bg-surface px-3 py-2 text-sm outline-none focus:border-accent"
        />
      </label>

      {error && <p className="text-sm text-red-600">{error}</p>}

      <div className="rounded-xl border border-border bg-surface2/60 p-4">
        <div className="flex justify-between text-sm text-textMuted">
          <span>Subtotal</span>
          <span>{formatCents(subtotalCents)}</span>
        </div>
        <div className="flex justify-between text-sm text-textMuted">
          <span>Delivery fee</span>
          <span>{deliveryFee > 0 ? formatCents(deliveryFee) : "—"}</span>
        </div>
        <div className="mt-2 flex justify-between border-t border-border pt-2 font-semibold text-text">
          <span>Total</span>
          <span>{formatCents(total)}</span>
        </div>
      </div>

      <Button type="submit" size="lg" disabled={submitting}>
        {submitting ? "Placing order…" : "Place order"}
      </Button>
      <p className="text-center text-xs text-textMuted">
        No payment is taken yet. We&apos;ll contact you to confirm your order and arrange payment before we start baking.
      </p>
    </form>
  );
}

