}

// Order times are rendered on the server, which runs in UTC. Show them in the
// bakery's local time zone instead. Change this if the bakery is elsewhere.
export const BUSINESS_TIME_ZONE = "America/Los_Angeles";

export function formatDateTime(iso: string | Date): string {
  return new Date(iso).toLocaleString("en-US", {
    timeZone: BUSINESS_TIME_ZONE,
    timeZoneName: "short",
    weekday: "short",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

