export type OrderStatus =
  | "pending"
  | "paid"
  | "in_kitchen"
  | "ready"
  | "out_for_delivery"
  | "completed"
  | "cancelled";

export type Order = {
  id: number;
  customer_id: number;
  status: OrderStatus;
  fulfillment: "pickup" | "delivery";
  fulfillment_at: string;
  contact_name: string;
  contact_phone: string;
  address: string | null;
  subtotal_cents: number;
  delivery_fee_cents: number;
  total_cents: number;
  notes: string | null;
  created_at: string;
};

export type OrderItem = {
  id: number;
  order_id: number;
  cake_id: number;
  quantity: number;
  unit_price_cents: number;
  selected_options: { kind: string; label: string; priceDeltaCents: number }[];
  message_on_cake: string | null;
  cake_name?: string;
};

export const DELIVERY_FEE_CENTS = 1200;
export const MIN_LEAD_HOURS = 24;
const MAX_LINES = 20;
const MAX_QTY_PER_LINE = 20;

/** What the browser is allowed to tell us about a cart line. Prices are NOT
 *  accepted from the client: they are re-read from the database below. */
export type OrderLineInput = {
  cakeId: number;
  quantity: number;
  selectedOptions: { kind: string; label: string }[];
  messageOnCake: string;
};

export class OrderValidationError extends Error {}

type PricedLine = {
  cakeId: number;
  quantity: number;
  unitPriceCents: number;
  options: { kind: string; label: string; priceDeltaCents: number }[];
  message: string | null;
};

/** Normalize untrusted cart JSON into OrderLineInput[] (shape only, no prices). */
export function parseOrderLines(raw: unknown): OrderLineInput[] {
  if (!Array.isArray(raw) || raw.length === 0 || raw.length > MAX_LINES) {
    throw new OrderValidationError("bad_items");
  }
  return raw.map((line) => {
    const l = (line ?? {}) as Record<string, unknown>;
    const cakeId = Number(l.cakeId);
    const quantity = Number(l.quantity);
    if (!Number.isInteger(cakeId) || !Number.isInteger(quantity) || quantity < 1 || quantity > MAX_QTY_PER_LINE) {
      throw new OrderValidationError("bad_items");
    }
    const opts = Array.isArray(l.selectedOptions) ? l.selectedOptions : [];
    return {
      cakeId,
      quantity,
      selectedOptions: opts.slice(0, 8).map((o) => {
        const r = (o ?? {}) as Record<string, unknown>;
        return { kind: String(r.kind ?? "").slice(0, 20), label: String(r.label ?? "").slice(0, 100) };
      }),
      messageOnCake: String(l.messageOnCake ?? "").trim().slice(0, 60),
    };
  });
}

/** Earliest allowed pickup/delivery time. */
export function earliestFulfillment(now = Date.now()): Date {
  return new Date(now + MIN_LEAD_HOURS * 60 * 60 * 1000);
}

export async function createOrder(params: {
  customerId: number;
  fulfillment: "pickup" | "delivery";
  fulfillmentAt: Date;
  contactName: string;
  contactPhone: string;
  address: string | null;
  notes: string | null;
  items: OrderLineInput[];
}): Promise<number> {
  const deliveryFee = params.fulfillment === "delivery" ? DELIVERY_FEE_CENTS : 0;

  return withTransaction(async (c) => {
    const cakeIds = Array.from(new Set(params.items.map((i) => i.cakeId)));
    const cakes = await c.query<{ id: number; base_price_cents: number }>(
      "SELECT id, base_price_cents FROM cakes WHERE id = ANY($1::bigint[]) AND active = true",
      [cakeIds],
    );
    const basePrice = new Map(cakes.rows.map((r) => [r.id, r.base_price_cents]));
    const opts = await c.query<{ cake_id: number; kind: string; label: string; price_delta_cents: number }>(
      "SELECT cake_id, kind, label, price_delta_cents FROM cake_options WHERE cake_id = ANY($1::bigint[])",
      [cakeIds],
    );

    const priced: PricedLine[] = params.items.map((item) => {
      const base = basePrice.get(item.cakeId);
      if (base === undefined) throw new OrderValidationError("cake_unavailable");
      const cakeOpts = opts.rows.filter((o) => o.cake_id === item.cakeId);
      const seenKinds = new Set<string>();
      const options = item.selectedOptions.map((sel) => {
        if (seenKinds.has(sel.kind)) throw new OrderValidationError("bad_items");
        seenKinds.add(sel.kind);
        const match = cakeOpts.find((o) => o.kind === sel.kind && o.label === sel.label);
        if (!match) throw new OrderValidationError("option_unavailable");
        return { kind: match.kind, label: match.label, priceDeltaCents: match.price_delta_cents };
      });
      const unitPriceCents = base + options.reduce((s, o) => s + o.priceDeltaCents, 0);
      return { cakeId: item.cakeId, quantity: item.quantity, unitPriceCents, options, message: item.messageOnCake || null };
    });

    const subtotal = priced.reduce((sum, l) => sum + l.unitPriceCents * l.quantity, 0);
    const total = subtotal + deliveryFee;

    const orderResult = await c.query<{ id: number }>(
      `INSERT INTO orders
         (customer_id, status, fulfillment, fulfillment_at, contact_name, contact_phone, address, subtotal_cents, delivery_fee_cents, total_cents, notes)
       VALUES ($1, 'pending', $2, $3, $4, $5, $6, $7, $8, $9, $10)
       RETURNING id`,
      [
        params.customerId,
        params.fulfillment,
        params.fulfillmentAt.toISOString(),
        params.contactName,
        params.contactPhone,
        params.address,
        subtotal,
        deliveryFee,
        total,
        params.notes,
      ],
    );
    const orderId = orderResult.rows[0].id;
    for (const line of priced) {
      await c.query(
        `INSERT INTO order_items (order_id, cake_id, quantity, unit_price_cents, selected_options, message_on_cake)
         VALUES ($1, $2, $3, $4, $5, $6)`,
        [orderId, line.cakeId, line.quantity, line.unitPriceCents, JSON.stringify(line.options), line.message],
      );
    }
    await c.query("INSERT INTO events (order_id, from_status, to_status) VALUES ($1, NULL, 'pending')", [orderId]);
    // Remember contact details for next time (only fills blanks).
    await c.query(
      "UPDATE users SET name = COALESCE(NULLIF(name, ''), $2), phone = COALESCE(NULLIF(phone, ''), $3) WHERE id = $1",
      [params.customerId, params.contactName, params.contactPhone],
    );
    return orderId;
  });
}

