export async function updateOrderStatus(orderId: number, toStatus: OrderStatus): Promise<void> {
  await withTransaction(async (c) => {
    const current = await c.query<{ status: OrderStatus }>("SELECT status FROM orders WHERE id = $1 FOR UPDATE", [
      orderId,
    ]);
    if (current.rows.length === 0) return;
    const fromStatus = current.rows[0].status;
    if (fromStatus === toStatus) return;
    await c.query("UPDATE orders SET status = $1 WHERE id = $2", [toStatus, orderId]);
    await c.query("INSERT INTO events (order_id, from_status, to_status) VALUES ($1, $2, $3)", [
      orderId,
      fromStatus,
      toStatus,
    ]);
  });
}

export type OrderEvent = { id: number; from_status: string | null; to_status: string; created_at: string };

