const FIELD = "rounded-lg border border-border bg-surface px-3 py-2 text-sm text-text outline-none focus:border-accent";

const NOTICES: Record<string, { tone: "ok" | "err"; text: string }> = {
  created: { tone: "ok", text: "Cake added with a starter set of sizes and flavors. Adjust them below." },
  "1": { tone: "ok", text: "Saved." },
  invalid: { tone: "err", text: "Give the cake a name and a price above $0." },
