export default async function AdminCakePage({
  params,
  searchParams,
}: {
  params: { id: string };
  searchParams: { saved?: string; error?: string };
}) {
  await requireAdminPage();
  const cakeId = Number(params.id);
  if (!Number.isInteger(cakeId)) notFound();
  const result = await getCakeForAdmin(cakeId);
  if (!result) notFound();
  const { cake, options } = result;
  const notice = NOTICES[searchParams.error ?? ""] ?? NOTICES[searchParams.saved ?? ""];

  return (
    <main className="mx-auto max-w-3xl px-4 py-10 sm:px-6">
      <Link href="/admin" className="inline-flex items-center gap-1 text-sm font-medium text-textMuted hover:text-accent">
        <ArrowLeft className="h-4 w-4" /> Back to admin
      </Link>
      <div className="mt-3 flex flex-wrap items-center justify-between gap-3">
        <h1 className="min-w-0 break-words font-display text-3xl font-semibold tracking-tight text-text">{cake.name}</h1>
        {cake.active && (
          <Link href={`/cakes/${cake.slug}`} className="text-sm font-medium text-accent hover:underline">
            View in shop
          </Link>
        )}
      </div>

      {notice && (
        <p
          className={`mt-4 rounded-lg border px-3 py-2 text-sm ${
            notice.tone === "ok" ? "border-emerald-200 bg-emerald-50 text-emerald-800" : "border-red-200 bg-red-50 text-red-700"
          }`}
        >
          {notice.text}
        </p>
      )}

      <form action={updateCakeAction} className="mt-6 grid gap-4 rounded-xl border border-border bg-surface p-5">
        <input type="hidden" name="cakeId" value={cake.id} />
        <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
          Name
          <input name="name" defaultValue={cake.name} required maxLength={200} className={FIELD} />
        </label>
        <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
          Description
          <textarea name="description" defaultValue={cake.description} rows={3} maxLength={2000} className={FIELD} />
        </label>
        <div className="grid gap-4 sm:grid-cols-2">
          <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
            Base price (USD)
            <input
              name="price"
              type="number"
              min="1"
              step="0.01"
              required
              defaultValue={(cake.base_price_cents / 100).toFixed(2)}
              className={FIELD}
            />
          </label>
          <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
            Dietary tags (comma separated)
            <input name="dietary" defaultValue={cake.dietary_tags.join(", ")} placeholder="gluten-free, vegan" className={FIELD} />
          </label>
        </div>
        <fieldset>
          <legend className="mb-2 text-sm font-medium text-text">Occasions</legend>
          <div className="flex flex-wrap gap-4">
            {OCCASIONS.map((o) => (
              <label key={o.slug} className="flex items-center gap-2 text-sm text-text">
                <input type="checkbox" name="occasion" value={o.slug} defaultChecked={cake.occasion_tags.includes(o.slug)} />
                {o.label}
              </label>
            ))}
          </div>
        </fieldset>
        <label className="flex items-center gap-2 text-sm font-medium text-text">
          <input type="checkbox" name="active" defaultChecked={cake.active} />
          Show this cake in the shop
        </label>
        <Button type="submit" className="justify-self-start">
          Save changes
        </Button>
      </form>

      <section className="mt-10">
        <h2 className="font-display text-xl font-semibold text-text">Customization choices</h2>
        <p className="mt-1 text-sm text-textMuted">
          Shoppers pick one choice from each group. The first choice in a group is selected by default.
        </p>
        <div className="mt-4 flex flex-col gap-4">
          {OPTION_KINDS.map(({ kind, label }) => {
            const group = options.filter((o) => o.kind === kind);
            return (
              <div key={kind} className="rounded-xl border border-border bg-surface p-4">
                <p className="text-sm font-semibold text-text">{label}</p>
                {group.length === 0 ? (
                  <p className="mt-1 text-sm text-textMuted">No {label.toLowerCase()} choices yet.</p>
                ) : (
                  <ul className="mt-2 flex flex-col gap-1">
                    {group.map((o) => (
                      <li key={o.id} className="flex items-center justify-between gap-3 text-sm">
                        <span className="min-w-0 truncate text-text">
                          {o.label}
                          {o.price_delta_cents > 0 && (
                            <span className="text-textMuted"> (+{formatCents(o.price_delta_cents)})</span>
                          )}
                        </span>
                        <form action={deleteOptionAction}>
                          <input type="hidden" name="cakeId" value={cake.id} />
                          <input type="hidden" name="optionId" value={o.id} />
                          <button
                            type="submit"
                            className="rounded-md p-1.5 text-textMuted hover:bg-surface2 hover:text-red-600"
                            aria-label={`Remove ${o.label}`}
