        <form action={addOptionAction} className="mt-4 grid gap-3 rounded-xl border border-dashed border-border p-4 sm:grid-cols-4">
          <input type="hidden" name="cakeId" value={cake.id} />
          <select name="kind" aria-label="Choice group" className={FIELD}>
