              <div className="flex items-start justify-between gap-4">
                <p className="min-w-0 break-words font-medium text-text">
                  {item.quantity} × {item.cake_name}
                </p>
                <span className="flex-shrink-0 font-medium text-text">
                  {formatCents(item.unit_price_cents * item.quantity)}
                </span>
              </div>
              <ul className="mt-2 flex flex-wrap gap-2">
                {item.selected_options.map((o) => (
                  <li key={`${o.kind}-${o.label}`} className="rounded-full bg-surface2 px-2.5 py-0.5 text-xs text-textMuted">
                    <span className="capitalize">{o.kind}</span>: {o.label}
                  </li>
                ))}
              </ul>
              {item.message_on_cake && (
                <p className="mt-2 break-words text-sm text-text">
                  Message on top: <span className="italic">&ldquo;{item.message_on_cake}&rdquo;</span>
                </p>
              )}
            </div>
          ))}
        </div>
        <div className="mt-4 flex flex-col gap-1 text-sm">
          <div className="flex justify-between text-textMuted">
            <span>Subtotal</span>
            <span>{formatCents(order.subtotal_cents)}</span>
          </div>
          <div className="flex justify-between text-textMuted">
            <span>Delivery fee</span>
            <span>{formatCents(order.delivery_fee_cents)}</span>
          </div>
          <div className="flex justify-between text-base font-semibold text-text">
            <span>Total</span>
            <span>{formatCents(order.total_cents)}</span>
          </div>
        </div>
      </section>

      <section className="mt-8">
        <h2 className="mb-3 font-display text-xl font-semibold text-text">History</h2>
        <ol className="flex flex-col gap-2 text-sm">
          {events.map((e) => (
            <li key={e.id} className="flex flex-wrap justify-between gap-2 border-b border-border pb-2">
              <span className="text-text">
                {e.from_status ? `${STATUS_LABELS[e.from_status] ?? e.from_status} → ` : "Order placed · "}
                {STATUS_LABELS[e.to_status] ?? e.to_status}
              </span>
              <span className="text-textMuted">{formatDateTime(e.created_at)}</span>
            </li>
          ))}
        </ol>
      </section>
    </main>
  );
}

"use client";

import Link from "next/link";
import { ShoppingBag } from "lucide-react";
import { useCart } from "@/lib/cart-context";
import { formatCents } from "@/lib/format";

/** Nudges a just-signed-in customer back to the cart they built before logging in. */
export function CartWaiting() {
  const { count, subtotalCents } = useCart();
  if (count === 0) return null;
  return (
    <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-accent/30 bg-accent/5 p-4">
      <p className="flex min-w-0 items-center gap-2 text-sm text-text">
        <ShoppingBag className="h-4 w-4 flex-shrink-0 text-accent" />
        Your cart is waiting: {count} cake{count === 1 ? "" : "s"}, {formatCents(subtotalCents)}.
      </p>
      <Link href="/checkout" className="text-sm font-semibold text-accent hover:underline">
        Continue to checkout
      </Link>
    </div>
  );
}

import { Check } from "lucide-react";
import { STATUS_LABELS } from "@/lib/format";

const PICKUP_STEPS = ["pending", "paid", "in_kitchen", "ready", "completed"];
const DELIVERY_STEPS = ["pending", "paid", "in_kitchen", "out_for_delivery", "completed"];

const STEP_LABELS: Record<string, string> = {
  ...STATUS_LABELS,
  pending: "Received",
  paid: "Confirmed",
  completed: "Enjoyed",
};

export function StatusTracker({ status, fulfillment }: { status: string; fulfillment: "pickup" | "delivery" }) {
  if (status === "cancelled") {
    return (
      <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
        This order was cancelled. Questions? Reply to your confirmation or reach out to us and we&apos;ll help.
      </div>
    );
  }
  const steps = fulfillment === "delivery" ? DELIVERY_STEPS : PICKUP_STEPS;
  // "ready" on a delivery order sits between kitchen and out-for-delivery.
  const normalized = fulfillment === "delivery" && status === "ready" ? "in_kitchen" : status;
  const currentIndex = Math.max(0, steps.indexOf(normalized));

  return (
    <ol className="grid grid-cols-5 gap-1" aria-label="Order progress">
      {steps.map((step, i) => {
        const done = i <= currentIndex;
        return (
          <li key={step} className="flex min-w-0 flex-col items-center gap-2 text-center">
            <div className="flex w-full items-center">
              <span className={`h-0.5 flex-1 ${i === 0 ? "bg-transparent" : done ? "bg-accent" : "bg-border"}`} />
              <span
                className={`flex h-7 w-7 flex-shrink-0 items-center justify-center rounded-full border text-xs font-semibold ${
                  done ? "border-accent bg-accent text-accentFg" : "border-border bg-surface text-textMuted"
                }`}
              >
                {done ? <Check className="h-3.5 w-3.5" /> : i + 1}
              </span>
              <span
                className={`h-0.5 flex-1 ${i === steps.length - 1 ? "bg-transparent" : i < currentIndex ? "bg-accent" : "bg-border"}`}
              />
            </div>
            <span className={`text-[11px] leading-tight sm:text-xs ${i === currentIndex ? "font-semibold text-text" : "text-textMuted"}`}>
              {STEP_LABELS[step] ?? step}
            </span>
          </li>
        );
      })}
    </ol>
  );
}

