export const OPTION_KINDS = [
  { kind: "size", label: "Size" },
  { kind: "flavor", label: "Flavor" },
  { kind: "filling", label: "Filling" },
  { kind: "frosting", label: "Frosting" },
] as const;

/** "Gluten-free, Nut free" -> ["gluten-free", "nut-free"] (max 6 tags). */
export function parseTags(raw: string): string[] {
  return Array.from(
    new Set(
      raw
        .split(",")
        .map((t) => t.trim().toLowerCase().replace(/\s+/g, "-").slice(0, 30))
        .filter(Boolean),
    ),
  ).slice(0, 6);
}
